const events=[];function eventHtml(e,i){return `<div class="event"><div class="eventpic event-cover"><img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcStick-ClT0IU4Wr4jPmMkxV9aU_4vqmKcBe1jtUbKpMw&s=10" alt="Capa ilustrativa do evento" loading="lazy" onerror="this.style.display='none'" /></div><div style="flex:1"><h3>${e.title}</h3><p><i data-lucide="calendar-days"></i> ${e.date}</p><p><i data-lucide="map-pin"></i> ${e.where} • ${e.dist}</p></div><button class="arrow" onclick="eventDetail(${i})"><i data-lucide="chevron-right"></i></button></div>`}function emptyEventsHtml(){return `<div class="events-empty"><div class="events-empty-icon"><i data-lucide="calendar-x-2"></i></div><h3>Sem eventos no momento</h3><p>Por enquanto, não há eventos cadastrados na sua região.</p><strong>Comece anunciando sua marca!</strong><p>Divulgue seu evento ou sua empresa para quem ama se movimentar.</p><button type="button" class="bigbtn" onclick="requestAdvertising()">Quero anunciar <i data-lucide="arrow-up-right"></i></button></div>`}
function eventDetail(i){let e=events[i];openModal(`<h2>${e.title}</h2><p class="eventdetail"><i data-lucide="calendar-days"></i> ${e.date}<br><i data-lucide="map-pin"></i> ${e.where}<br><i data-lucide="person-standing"></i> Distância: ${e.dist}<br><br>Evento demonstrativo. O link oficial de inscrição ainda não foi cadastrado.</p><button class="bigbtn" onclick="closeModal()">Voltar aos eventos</button>`)}function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('on',b.dataset.page===id));window.scrollTo(0,0);if(id==='profile')renderReminderSettings();if(id==='ranking')loadCommunityRanking();if(id==='track')setTimeout(()=>{initMap();if(!running&&!starting)resetCurrentRoute();focusUserLocation()},80);updateActivityUI();render()}function homeStartAction(){showScreen('track')}function chooseActivity(m){setMode(m);showScreen('track')}function setMode(m){if(running)return;mode=m;$('selrun').classList.toggle('on',m==='Corrida');$('selwalk').classList.toggle('on',m==='Caminhada');$('selbike').classList.toggle('on',m==='Ciclismo');$('livepaceLabel').textContent=m==='Ciclismo'?'VELOCIDADE MÉDIA':m==='Caminhada'?'RITMO DE CAMINHADA':'RITMO DE CORRIDA';updateLive()}let goal=3,mode='Corrida';function changeGoal(n){if(running)return;goal=Math.max(1,Math.min(100,goal+n));$('goalval').textContent=goal}
let map,routeLine,marker,hasCentered=false,watchId=null,running=false,paused=false,points=[],distance=0,elapsed=0,timer=null,lastTick=0,starting=false,countdownTimer=null,voiceHalf=false,voiceNear=false,lastAcceptedTime=0;function initMap(){if(map){map.invalidateSize();return}if(typeof L==='undefined'){$('map').innerHTML='<div class="map-placeholder">Mapa indisponível sem conexão.</div>';return} $('map').innerHTML='';map=L.map('map',{zoomControl:false}).setView([-7.23,-44.55],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);routeLine=L.polyline([],{color:'#83ce1c',weight:6}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);map.invalidateSize()}
function focusUserLocation(){if(!navigator.geolocation||!map)return;navigator.geolocation.getCurrentPosition(pos=>{if(!map)return;const lat=pos.coords.latitude,lng=pos.coords.longitude;if(!marker)marker=L.circleMarker([lat,lng],{radius:8,color:'white',weight:3,fillColor:'#72c625',fillOpacity:1}).addTo(map);else marker.setLatLng([lat,lng]);map.setView([lat,lng],17,{animate:true});hasCentered=true;$('gpsstatus').textContent='GPS ativo'},()=>{$('gpsstatus').textContent='Permita o GPS'},{enableHighAccuracy:true,maximumAge:0,timeout:12000})}function haversine(a,b){const r=6371,toRad=x=>x*Math.PI/180,dLat=toRad(b.lat-a.lat),dLon=toRad(b.lng-a.lng);const q=Math.sin(dLat/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLon/2)**2;return 2*r*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))}function formatTime(s){s=Math.floor(s);return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}function pace(){return mode==='Ciclismo'?speedText(elapsed,distance):paceText(elapsed,distance)}function speedText(seconds,km){if(km<.05||seconds<5)return '—';return (km*3600/seconds).toFixed(1).replace('.',',')+' km/h'}function paceText(seconds,km){if(km<.05||seconds<5)return '—';const total=Math.round(seconds/km);if(!Number.isFinite(total)||total<=0)return '—';return Math.floor(total/60)+"'"+String(total%60).padStart(2,'0')+'"'}function updateLive(){$('livekm').textContent=distance.toFixed(2).replace('.',',');$('livetime').textContent=formatTime(elapsed);$('livepace').textContent=pace();$('livecal').textContent=estimatedCalories(distance,mode);updateActivityUI()}function estimatedCalories(km,activity){return Math.max(0,Math.round(km*(activity==='Caminhada'?0.53:activity==='Ciclismo'?0.45:1)*(Number(data.weight)||70)))}function speakMotivation(message){if(!$('voiceenabled').checked||!('speechSynthesis' in window))return;try{speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(message);speech.lang='pt-BR';speech.rate=1;speechSynthesis.speak(speech)}catch(e){console.warn('Narração indisponível',e)}}function checkMilestones(){if(goal<=0)return;if(!voiceHalf&&distance>=goal*.5){voiceHalf=true;speakMotivation('Muito bem! Você já completou metade do seu objetivo. Continue firme, você está indo muito bem!')}if(!voiceNear&&distance>=goal*.9){voiceNear=true;speakMotivation('Falta muito pouco! Você já percorreu noventa por cento da sua meta. Vamos terminar com força!')}}function onPosition(pos){const p={lat:pos.coords.latitude,lng:pos.coords.longitude,acc:pos.coords.accuracy};$('gpsstatus').textContent='● GPS ativo';if(map){if(!marker)marker=L.circleMarker([p.lat,p.lng],{radius:8,color:'white',weight:3,fillColor:'#72c625',fillOpacity:1}).addTo(map);else marker.setLatLng([p.lat,p.lng]);if(!hasCentered){map.setView([p.lat,p.lng],17);hasCentered=true}else if(running&&!paused){map.panTo([p.lat,p.lng],{animate:true})}}if(!running||paused||p.acc>(mode==='Ciclismo'?55:mode==='Caminhada'?30:40))return;const prev=points[points.length-1];if(prev){const d=haversine(prev,p);const now=pos.timestamp||Date.now();const delta=(now-lastAcceptedTime)/1000;if(d<(mode==='Ciclismo'?.012:mode==='Caminhada'?.003:.006)||delta<=0||d/delta*3600>(mode==='Ciclismo'?85:mode==='Caminhada'?16:35))return;distance+=d}points.push(p);lastAcceptedTime=pos.timestamp||Date.now();if(routeLine)routeLine.setLatLngs(points.map(q=>[q.lat,q.lng]));checkMilestones();updateLive()}function onGpsError(err){$('gpsstatus').textContent='GPS indisponível';if(running)openModal('<h2>Localização indisponível</h2><p class="eventdetail">Confira se a localização está ativada e se o site está aberto por HTTPS ou localhost. O cronômetro continuará funcionando, mas sem GPS a distância não será medida.</p><button class="bigbtn" onclick="closeModal()">Entendi</button>')}
function resetCurrentRoute(){points=[];distance=0;elapsed=0;lastAcceptedTime=0;voiceHalf=false;voiceNear=false;hasCentered=false;if(routeLine)routeLine.setLatLngs([]);if(marker&&map){map.removeLayer(marker);marker=null}updateLive();focusUserLocation()}
function startRun(){if(running||starting)return;if(!navigator.geolocation){alert('Seu navegador não oferece geolocalização.');return}initMap();starting=true;resetCurrentRoute();$('startcontrols').classList.add('hide');$('countdown').classList.remove('hide');let count=5;$('countnumber').textContent=count;speakCountdown(count);countdownTimer=setInterval(()=>{count--;if(count>0){$('countnumber').textContent=count;speakCountdown(count);return}clearInterval(countdownTimer);countdownTimer=null;$('countnumber').textContent='VAI!';speakCountdown(0);setTimeout(()=>{$('countdown').classList.add('hide');starting=false;beginTracking()},450)},1000)}
function beginTracking(){running=true;paused=false;updateActivityUI();$('activecontrols').classList.remove('hide');$('pausebtn').innerHTML='<i data-lucide="pause"></i> PAUSAR';lastTick=Date.now();timer=setInterval(()=>{const now=Date.now();if(!paused)elapsed+=(now-lastTick)/1000;lastTick=now;updateLive()},250);watchId=navigator.geolocation.watchPosition(onPosition,onGpsError,{enableHighAccuracy:true,maximumAge:0,timeout:15000});updateLive()}
function togglePause(){paused=!paused;updateActivityUI();lastTick=Date.now();$('pausebtn').innerHTML=paused?'<i data-lucide="play"></i> RETOMAR':'<i data-lucide="pause"></i> PAUSAR'}function finishRun(){if(!running)return;clearInterval(timer);if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;running=false;paused=false;updateActivityUI();$('activecontrols').classList.add('hide');$('startcontrols').classList.remove('hide');let run={id:Date.now(),mode,km:distance,seconds:Math.round(elapsed),calories:estimatedCalories(distance,mode),date:new Date().toISOString(),locality:data.locality||'',route:points.map(p=>[p.lat,p.lng])};data.runs.unshift(run);save();render();if(sessionToken&&run.seconds>0){api({action:'updatePerformance',token:sessionToken,performance:dailyPerformance(run.mode)}).then(()=>loadCommunityRanking()).catch(e=>console.warn('Atividade não sincronizada:',e))}showFinishSponsor(run);celebrateActivityFinish()}function showResult(r){if(!r)return;openModal(`<div class="result-head"><span class="eyebrow">ATIVIDADE CONCLUÍDA</span><h2>${escapeHtml(r.mode)} • ${Number(r.km).toFixed(2).replace('.',',')} km</h2><p>${formatTime(r.seconds)} de duração • ${r.calories??estimatedCalories(r.km,r.mode)} kcal estimadas</p></div><div class="result-actions"><button class="bigbtn" onclick="openPhotoComposer(${r.id})"><i data-lucide="image"></i> Compartilhar conquista</button><button class="bigbtn dark" onclick="closeModal();showScreen('progress')"><i data-lucide="chart-no-axes-column-increasing"></i> Ver progresso completo</button></div>`);refreshIcons()}
function formatPace(r){return r.mode==='Ciclismo'?speedText(r.seconds,r.km):paceText(r.seconds,r.km)}function unitFor(r){return r.mode==='Ciclismo'?'':'/km'}

// Desenha somente o percurso real registrado pelo GPS, sem simular trajetos.
function routeCoordinates(route,width,height,pad=28){
 if(!Array.isArray(route))return [];
 const pts=route.filter(p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(+p[0])&&Number.isFinite(+p[1]));
 if(pts.length<2)return [];
 const meanLat=pts.reduce((sum,p)=>sum+(+p[0]),0)/pts.length;
 const factor=Math.cos(meanLat*Math.PI/180);
 const coords=pts.map(p=>({x:(+p[1])*factor,y:-(+p[0])}));
 const xs=coords.map(p=>p.x),ys=coords.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);
 const spanX=Math.max(xmax-xmin,1e-8),spanY=Math.max(ymax-ymin,1e-8);
 const scale=Math.min((width-pad*2)/spanX,(height-pad*2)/spanY);
 const ox=(width-spanX*scale)/2,oy=(height-spanY*scale)/2;
 return coords.map(p=>({x:ox+(p.x-xmin)*scale,y:oy+(p.y-ymin)*scale}));
}
function drawRouteOnCanvas(c,route,x,y,w,h,transparent=false){
 const pts=routeCoordinates(route,w,h,36);
 if(!pts.length)return false;
 c.save();c.translate(x,y);c.lineCap='round';c.lineJoin='round';
 c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));
 c.strokeStyle=transparent?'rgba(0,0,0,.9)':'rgba(0,0,0,.55)';c.lineWidth=24;c.stroke();
 c.strokeStyle='#b6f43c';c.lineWidth=13;c.stroke();
 for(const [p,color] of [[pts[0],'#fff'],[pts[pts.length-1],'#b6f43c']]){c.beginPath();c.arc(p.x,p.y,13,0,Math.PI*2);c.fillStyle=color;c.fill();c.strokeStyle='#142000';c.lineWidth=4;c.stroke()}
 c.restore();return true;
}
function routePreviewHtml(r){
 const pts=routeCoordinates(r.route,310,150,15);
 if(!pts.length)return '<p class="route-empty">Percurso não disponível: GPS insuficiente nesta atividade.</p>';
 const path=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');
 return `<div class="route-preview"><div class="route-caption">SEU PERCURSO GPS</div><svg viewBox="0 0 310 150" role="img" aria-label="Traçado do percurso da atividade"><path d="${path}" stroke="#b6f43c" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${pts[0].x}" cy="${pts[0].y}" r="6" fill="white"/><circle cx="${pts[pts.length-1].x}" cy="${pts[pts.length-1].y}" r="6" fill="#b6f43c"/></svg></div>`;
}

