function renderReminderSettings(){const r=data.reminder||{days:[1,2,3,4,5],time:'07:00',enabled:false};$('reminderTime').value=r.time||'07:00';$('reminderEnabled').checked=!!r.enabled;$('reminderDays').innerHTML=weekdays.map((day,i)=>`<label><input type="checkbox" value="${i}" ${r.days.includes(i)?'checked':''}><span>${day}</span></label>`).join('')}
async function saveReminder(){const days=[...document.querySelectorAll('#reminderDays input:checked')].map(x=>Number(x.value));const enabled=$('reminderEnabled').checked;const time=$('reminderTime').value||'07:00';if(enabled&&!days.length){alert('Escolha pelo menos um dia.');return}const btn=document.querySelector('button[onclick="saveReminder()"]');const label=btn?.innerHTML;if(btn){btn.disabled=true;btn.innerHTML='<span class="reminder-spinner"></span> Salvando lembrete...'}try{if(!sessionToken)throw Error('Entre na sua conta para salvar seu lembrete.');await api({action:'saveReminder',token:sessionToken,enabled,days,time});data.reminder={enabled,days,time};save();alert(enabled?'Lembrete ativado! Você receberá e-mails motivacionais nos dias escolhidos, próximo do horário programado.':'Lembretes desativados com sucesso.')}catch(e){alert('Não foi possível salvar na planilha: '+e.message)}finally{if(btn){btn.disabled=false;btn.innerHTML=label}}}
let lastReminderKey='';setInterval(()=>{const r=data.reminder;if(!r?.enabled||!r.days?.includes(new Date().getDay()))return;const now=new Date(),hm=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'),key=now.toDateString()+hm;if(hm===r.time&&lastReminderKey!==key){lastReminderKey=key;alert('Uruçuí em Movimento: hora de cuidar de você! Vamos caminhar ou correr hoje?')}},30000);
